describe('Permissions Error on Content Edit', () => {
  beforeEach(() => {
    cy.visit('/content/edit');
  });

  it('should display permissions error when editing another user’s content', () => {
    // Intercept the API call to edit content
    cy.intercept('PUT', '/api/content/123').as('editContent');

    // Navigate to edit another user's content
    cy.get('[data-testid="content-selector"]').click();
    cy.get('[data-testid="content-title-input"]').type('Unauthorized Content');
    cy.get('[data-testid="content-body-textarea"]').type('This is content belonging to another user.');

    // Attempt to save the changes
    cy.get('[data-testid="save-button"]').click();

    // Wait for the API call
    cy.wait('@editContent');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'You do not have permission to edit this content');

    // Verify error styling
    cy.get('[data-testid="error-message"]')
      .should('have.class', 'text-danger');

    // Verify content was not saved
    cy.get('[data-testid="content-title-input"]')
      .should('have.value', 'Unauthorized Content');
    cy.get('[data-testid="content-body-textarea"]')
      .should('have.value', 'This is content belonging to another user.');

    // Verify user is still on the edit page
    cy.url().should('include', '/content/edit');
  });

  it('should prevent unauthorized content modification and show appropriate error', () => {
    // Intercept the API call and mock a 433 error response
    cy.intercept('PUT', '/api/content/456', {
      statusCode: 433,
      body: { error: 'Forbidden' }
    }).as('forbiddenEdit');

    // Navigate to edit another user's content
    cy.get('[data-testid="content-selector"]').click();
    cy.get('[data-testid="content-title-input"]').type('Secret Document');
    cy.get('[data-testid="content-body-textarea"]').type('This should not be saved.');

    // Attempt to save the changes
    cy.get('[data-testid="save-button"]').click();

    // Wait for the forbidden API call
    cy.wait('@forbiddenEdit');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Permission denied');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]')
      .should('be.visible');

    // Verify content was not modified
    cy.get('[data-testid="content-title-input"]')
      .should('have.value', 'Secret Document');
    cy.get('[data-testid="content-body-textarea"]')
      .should('have.value', 'This should not be saved.');

    // Verify user can still navigate away
    cy.get('[data-testid="back-button"]').click();
    cy.get('[data-testid="content-list"]').should('be.visible');
  });
});
